insert into artists (id,name,name_en,discipline,tags,tagline,bio,philosophy,instagram,city,hue,sort,is_demo) values ('xiaowu','林小霧','Lin Xiaowu','插畫',array['插畫','城市']::text[],'畫霧氣裡的城市夜景，和每一隻失眠的貓。','台北出生、在基隆住了六年的插畫創作者。擅長以低彩度藍紫描繪城市夜晚，作品常出現頂樓、便利商店與不睡覺的貓。','我想畫的是那些大家都經過、卻沒有停下來看的時刻。','@xiaowu.fog','基隆',275,0,true);
insert into artists (id,name,name_en,discipline,tags,tagline,bio,philosophy,instagram,city,hue,sort,is_demo) values ('atu','阿凸','ATU','角色設計',array['角色','幽默']::text[],'一顆很容易生氣的饅頭，和他吵吵鬧鬧的朋友們。','角色設計師，曾任動畫公司美術。2021 年創造角色「饅頭」，以短篇四格記錄上班族的小情緒。','生氣也沒關係，生完氣去吃宵夜就好。','@atu.mantou','台中',80,1,true);
insert into artists (id,name,name_en,discipline,tags,tagline,bio,philosophy,instagram,city,hue,sort,is_demo) values ('chenyan','陳硯','Chen Yan','木刻版畫',array['版畫','植物']::text[],'用木刻線條，一株一株記錄島嶼上的原生植物。','版畫創作者，長期田野調查台灣低海拔原生植物，每件作品皆從手繪草稿、刻版到手工拓印完成。','刻刀慢，但植物長得更慢。我只是試著跟上它們。','@chenyan.woodcut','花蓮',150,2,true);
insert into artists (id,name,name_en,discipline,tags,tagline,bio,philosophy,instagram,city,hue,sort,is_demo) values ('mori','森野','Mori','攝影',array['攝影','日常']::text[],'海邊、鐵皮屋，與午後三點剛好斜進來的光。','底片與數位並用的攝影師，作品聚焦台灣西海岸小鎮的建築與光線。','光每天都來，只是我們不一定在家。','@mori.3pm','台南',225,3,true);
insert into artists (id,name,name_en,discipline,tags,tagline,bio,philosophy,instagram,city,hue,sort,is_demo) values ('riri','黃日日','Huang Riri','字體／平面設計',array['字體','文字']::text[],'把阿嬤常說的台語俗諺，排成好看的字。','平面設計師，專注中文字體與在地語彙，將台語俗諺重新設計成可以帶在身上的字。','一句話被好好排版，就會被好好記住。','@riri.type','台北',45,4,true);
insert into artists (id,name,name_en,discipline,tags,tagline,bio,philosophy,instagram,city,hue,sort,is_demo) values ('sura','蘇拉','Sura','拼貼／複合媒材',array['拼貼','復古']::text[],'用舊報紙、市場傳單，拼一個有點荒謬的未來。','拼貼藝術家，蒐集各地傳統市場的傳單與舊報紙，重組成帶有復古未來感的畫面。','舊東西不是過去，它們只是在等新的排列方式。','@sura.collage','高雄',20,5,true);
insert into collections (id,name,name_en,season,concept,description,hue,sort,is_demo) values ('night-market','夜市研究所','Night Market Lab','2026 秋冬','當失眠的貓遇上愛生氣的饅頭，一起去逛凌晨的夜市。','林小霧的藍紫夜景，加上阿凸的饅頭角色，把夜市的燈籠、煙霧和排隊人潮，變成可以穿上身、背出門的故事。系列以低彩度夜色與一抹燈籠橘為主調。',285,0,true);
