insert into collections (id,name,name_en,season,concept,description,hue,sort,is_demo) values ('island-flora','島嶼植物誌','Island Flora','2026 限定','一刀一刀刻出的台灣原生植物，從版畫走進日常。','陳硯走訪東部低海拔山林，選出萍蓬草、姑婆芋等原生植物，以木刻版畫為原稿，製作限量簽名版畫與刺繡單品。',150,1,true);
