insert into collections (id,name,name_en,season,concept,description,hue,sort,is_demo) values ('afternoon-3pm','午後三點','3 PM','2026 秋季','影像與文字的對話：關於慢下來的那一個小時。','森野的西海岸攝影，搭配黃日日設計的台語俗諺字體。一張照片、一句話，提醒自己「慢慢仔來，比較快」。',215,2,true);
