insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p1','sleepless-cat-tee','失眠貓夜景 T 恤','xiaowu','tees','night-market',980,'limited',null,true,92,'2026-10-20',array['奶油白','墨黑']::text[],array['S','M','L','XL']::text[],18,'100% 精梳棉 230g／m²，水性環保印刷。','反面冷水手洗或洗衣袋輕柔洗，勿烘乾、勿直接熨燙圖案。','見尺寸表','凌晨兩點的頂樓，一隻貓和整座城市一起醒著。原畫為林小霧的同名插畫，印刷前經藝術家親自校色三次。',275,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p2','mantou-tote','饅頭生氣中 帆布托特包','atu','bags','night-market',690,'instock',null,true,88,'2026-10-18',array['自然米']::text[],array[]::text[],40,'12 安士厚磅帆布，內附小口袋。','局部手洗，陰乾。','寬 38 × 高 40 × 底 10 cm','饅頭今天也很生氣，但他還是幫你裝好了便當、筆電，跟一點點耐心。',80,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p3','lantern-stickers','夜市燈籠 貼紙組（8 入）','atu','stickers','night-market',180,'instock',null,true,95,'2026-10-15',array[]::text[],array[]::text[],120,'霧面防水 PVC，可貼筆電、水壺與行李箱。','避免長時間曝曬。','每張約 5–7 cm','烤香腸、珍奶、彈珠台，還有一顆在排隊時越來越生氣的饅頭。',60,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p4','water-lily-print','台灣萍蓬草 木刻版畫','chenyan','posters','island-flora',2400,'limited',null,true,70,'2026-10-10',array[]::text[],array['A3']::text[],6,'手漉和紙，油性版畫墨，手工拓印；限量 30 張，附簽名與編號。','避免陽光直射與潮濕，建議裱框保存。','29.7 × 42 cm（不含框）','萍蓬草是台灣特有的水生植物，曾一度瀕臨消失。陳硯在桃園埤塘邊畫了三個夏天的草稿，才刻下這一版。',150,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p5','taro-leaf-cap','姑婆芋 刺繡老帽','chenyan','hats','island-flora',880,'preorder','2026-12-15',true,81,'2026-10-22',array['森林綠','奶油白']::text[],array[]::text[],0,'水洗棉斜紋布，正面電腦刺繡，後方金屬扣可調。','手洗，勿漂白。','頭圍 56–60 cm 可調','小時候下雨天，阿公會隨手摘一片姑婆芋當傘。這頂帽子把那片葉子繡了回來。',140,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p6','3pm-poster','午後三點 攝影海報','mori','posters','afternoon-3pm',1200,'instock',null,true,76,'2026-10-05',array[]::text[],array['A3','A2']::text[],25,'250g 美術紙，藝術微噴輸出。','避免陽光直射，建議裱框。','A3 29.7 × 42 cm／A2 42 × 59.4 cm','台南安平的一面鐵皮牆，下午三點零七分，光剛好斜進來十二分鐘。',225,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p7','tin-house-longsleeve','鐵皮屋 長袖上衣','mori','tees','afternoon-3pm',1280,'preorder','2026-12-05',true,64,'2026-10-25',array['霧灰','墨黑']::text[],array['S','M','L','XL']::text[],0,'棉 95%／彈性纖維 5%，背面大圖數位直噴。','反面冷水洗，勿烘乾。','見尺寸表','西海岸小鎮常見的彩色鐵皮屋，被森野拍成一整個系列。這件把其中一棟穿在你背上。',215,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p8','slowly-mug','「慢慢仔來」字體馬克杯','riri','living','afternoon-3pm',520,'instock',null,true,90,'2026-09-28',array['奶油白']::text[],array[]::text[],32,'陶瓷，容量 350 ml，可微波。','建議手洗以保持字體印刷完整。','直徑 8.5 × 高 9.5 cm','「慢慢仔來，比較快。」黃日日把阿嬤最常說的這句話，設計成每天早上會看到的字。',45,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p9','ho-ka-tsai-hat','「好佳哉」漁夫帽','riri','hats',null,820,'soldout',null,false,85,'2026-08-30',array['磚紅']::text[],array['M','L']::text[],0,'棉麻混紡，帽簷內縫字體織標。','手洗，平放陰乾。','M 頭圍 57 cm／L 頭圍 59 cm','好佳哉——幸好。給每一個差點遲到、但還是趕上了的早晨。',30,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p10','market-flyer-backpack','市場傳單拼貼 束口後背包','sura','bags',null,760,'instock',null,false,72,'2026-09-15',array['自然米']::text[],array[]::text[],22,'再生聚酯纖維，滿版熱昇華印刷。','手洗，陰乾。','寬 35 × 高 45 cm','高雄三民市場的特價傳單、舊報紙分類廣告，被蘇拉剪成一張奇怪又熱鬧的未來地圖。',20,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p11','future-breakfast-stickers','未來早餐店 貼紙組（6 入）','sura','stickers',null,160,'limited',null,false,68,'2026-09-20',array[]::text[],array[]::text[],9,'亮面防水 PVC。','避免長時間曝曬。','每張約 6 cm','2087 年的早餐店，還是賣蘿蔔糕加蛋，只是老闆娘換成了機器人。',10,true);
insert into products (id,slug,name,artist_id,category_id,collection_id,price,status,ship_date,is_new,popularity,released_at,colors,sizes,stock,material,care,dimensions,story,hue,is_demo) values ('p12','fog-city-coasters','霧夜城市 陶瓷杯墊組（2 入）','xiaowu','living',null,450,'instock',null,false,60,'2026-09-10',array[]::text[],array[]::text[],15,'吸水陶瓷，底部軟木防滑。','濕布擦拭即可。','直徑 10 cm','兩片杯墊、兩個窗口，一個看港口，一個看便利商店。',265,true);
