insert into faqs (question,answer,sort) values ('商品是正版授權嗎？','正式營運後，所有商品皆在與藝術家簽訂授權合約後製作，並標示創作者署名。目前網站內的藝術家與商品皆為示意資料。',0);
insert into faqs (question,answer,sort) values ('預購商品什麼時候出貨？','每件預購商品頁都會標示預計出貨日，若有延遲將以 Email 主動通知（通知功能待串接）。',1);
insert into faqs (question,answer,sort) values ('可以退換貨嗎？','依消費者保護法享有七天猶豫期（非試用期）。限量簽名版畫等個別商品若有例外規定，會在商品頁清楚標示。',2);
insert into faqs (question,answer,sort) values ('運費怎麼計算？','宅配 NT$100、超商取貨 NT$60，單筆滿 NT$1,500 免運（示意規則）。',3);
insert into faqs (question,answer,sort) values ('可以開立統一編號發票嗎？','電子發票功能待串接，正式上線後可於結帳時填寫統一編號。',4);
insert into faqs (question,answer,sort) values ('我是創作者，要怎麼合作？','請至「藝術家合作」頁面填寫申請表，團隊會在初審後與你聯繫。',5);
insert into info_sections (page,page_title,heading,body,sort) values ('shipping','配送說明','配送方式','提供宅配到府與超商取貨（7-ELEVEN、全家）。物流服務尚待串接，以下為示意規則。',0);
insert into info_sections (page,page_title,heading,body,sort) values ('shipping','配送說明','運費','宅配 NT$100、超商取貨 NT$60；單筆訂單滿 NT$1,500 免運。',1);
insert into info_sections (page,page_title,heading,body,sort) values ('shipping','配送說明','出貨時間','現貨商品於付款完成後 3 個工作天內出貨；預購商品依商品頁標示之預計出貨日陸續寄出。',2);
insert into info_sections (page,page_title,heading,body,sort) values ('shipping','配送說明','離島與海外','離島及海外配送尚未開放，正式上線前將另行公告。',3);
insert into info_sections (page,page_title,heading,body,sort) values ('returns','退換貨政策','七天猶豫期','依消費者保護法，收到商品次日起七天內可申請退貨；猶豫期並非試用期，商品須保持全新狀態與完整包裝。',0);
insert into info_sections (page,page_title,heading,body,sort) values ('returns','退換貨政策','例外情形','依「通訊交易解除權合理例外情事適用準則」，部分客製或易於複製之商品可能不適用，將於商品頁事先標示。',1);
insert into info_sections (page,page_title,heading,body,sort) values ('returns','退換貨政策','申請方式','線上退換貨申請功能待串接；正式上線前請以客服信箱聯繫（示意）。',2);
insert into info_sections (page,page_title,heading,body,sort) values ('returns','退換貨政策','退款','確認退貨商品後，依原付款方式退款，時間依金流服務商規定。',3);
insert into info_sections (page,page_title,heading,body,sort) values ('privacy','隱私權政策','蒐集目的','處理訂單、配送、客服、電子報寄送與藝術家合作申請。',0);
insert into info_sections (page,page_title,heading,body,sort) values ('privacy','隱私權政策','蒐集類別','姓名、聯絡方式、收件資訊、訂單紀錄，以及合作申請所提供之作品集連結。',1);
insert into info_sections (page,page_title,heading,body,sort) values ('privacy','隱私權政策','利用期間與方式','於蒐集目的存續期間內，僅用於上述目的，不會販售予第三方。',2);
insert into info_sections (page,page_title,heading,body,sort) values ('privacy','隱私權政策','你的權利','你可隨時請求查詢、更正、停止利用或刪除個人資料。',3);
insert into info_sections (page,page_title,heading,body,sort) values ('terms','服務條款','服務說明','本網站提供原創藝術家聯名商品之瀏覽與購買服務。目前為示意版本，尚未開放實際交易。',0);
insert into info_sections (page,page_title,heading,body,sort) values ('terms','服務條款','商品與價格','商品價格以新台幣（NT$）計價，實際售價以結帳頁面為準。',1);
insert into info_sections (page,page_title,heading,body,sort) values ('terms','服務條款','智慧財產權','網站中所有作品著作權屬原創作者所有，未經授權不得重製、改作或商業使用。',2);
insert into info_sections (page,page_title,heading,body,sort) values ('terms','服務條款','準據法','本條款以中華民國法律為準據法。',3);
